import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易經傳集解卷十二","description":"周易經傳集解 - 周易經傳集解卷十二","frontmatter":{"title":"周易經傳集解卷十二","description":"周易經傳集解 - 周易經傳集解卷十二"},"headers":[],"relativePath":"classics/jingchuan-jijie/013.md","filePath":"classics/jingchuan-jijie/013.md"}'),r={name:"classics/jingchuan-jijie/013.md"};function c(o,a,l,d,p,j){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易經傳集解卷十二",tabindex:"-1"},[n("周易經傳集解卷十二 "),e("a",{class:"header-anchor",href:"#周易經傳集解卷十二","aria-label":"Permalink to “周易經傳集解卷十二”"},"​")],-1),e("p",null,"欽定四庫全書周易經傳集解剝復卷十二 ​宋林栗撰。序卦曰：賁者，飾也。致飾然後亨則盡矣，故受之以剝。剝之成卦，「賁」之變也。自「賁」之剝，上艮不動，離變為坤，易其二剛而成剝也。夫所以為「賁」者，「離」與「艮」也。離為火，艮坤為土，火熄而為土，則盡矣。所以為「賁」者，剛與柔也。剛為質，柔為文，質化而為文，則盡矣。夫質文之為言，猶本末也。無本不立，無文不行。然使天下蕩然曰趨於文，則末勝而本離矣。故夫離之在「賁」，非能亨也，柔來文之，故亨。艮之在「賁」，非能往也，剛上文之，故「小利有攸往」。然則當賁之時，末既勝矣，況又變而為坤哉！是以謂之「剝」也。蓋孔子嘗自筮，得「賁」焉，愀然有不平之色。子張進曰：「筮得賁，吉，而愀然，何也？」子曰：「以其離在艮下，山下有火謂之賁，非正色之卦也。吾聞丹漆不文，白玉不凋，質有餘，不受飾故也。是以賁之交爻，不言餘色而專言潔白；不言華飾而專言粉素，蓋將以反其質歟！」剝：不利有攸往。彖曰：「剝」，剝也，柔變剛也。「不利有攸往」，小人長也。順而止之，觀象也。君子尚消息盈虛，天行也。下坤上「艮」，成卦曰「剝」者，初為坤，二與三亦為「坤」，四為「艮」。然則「剝」之四象，惟以「坤」、「艮」言之。「坤」，土也；「艮」亦土也。「坤」為平地，而「艮」則山也。草木華實莫不盡落，惟有山在地上耳，此卦之所以為「剝」也。故子曰：「剝，剝也，柔變剛也。」「剝，不利有攸往」，何謂也？曰：方「賁」之時，「小利有攸往」而已，況於「剝」乎？「剝」者，陰消陽之卦也。陽為君子，陰為小人。五陽為主而一陰為客，君子盛而小人窮矣，故其卦為「夬」，其彖曰：「利有攸往」。五陰為主而一陽為客，小人盛而君子微矣，故其卦為「剝」，其彖曰：「不利有攸往」。凡此皆為君子言之也。「坤」，順也；「艮」，止也。君子觀此之象，是以順時而止之也，故子曰：「不利有攸往，小人長也。順而止之，觀象也。」夫子既已釋其象，又從而贊之曰：「君子尚消息盈虛，天行也。」蓋言君子小人，如天之行，四時之運，一消一息，一盈一虛。以陽言之，則息於春，盈於夏，消於秋，虛於冬。方其消也，而欲其息，方其虛也，而求其盈，不可得也。君子是以尚其理，而不敢必其道之行也。雖然，聖人之作易也，其於君子，愛之之至也；其於小人，憂之之深也。愛之至，則畀其周身之防；憂之深，則開其為善之利。至於轉禍為福，撥亂為治，蓋聖人之本心也。故夫復、臨、泰、壯、夬者，五陽之序也。姤、遁、否、觀、剝者，五陰之序也。而易之序則不然，陽先退而後進，故自泰而之臨，自臨而之復，然後繼之以壯、夬者，所以成其治也。陰先進而後退，故自否而之觀，自觀而之剝，然後反之以遁、姤者，所以止其亂也。以為治亂皆任之自然，則人事廢矣。是故四卦，凡彖與爻，吉多而兇少。至於否、剝，猶有「吉亨無不利」之辭，不亦轉禍為福之意歟！象曰：山附於地，剝。上以厚下安宅。山者，艮也；地者，「坤」也。山附於地，無餘蘊矣。君子觀此之象，以為草木盡剝，而山巍然獨存者，非以其基厚故歟？山有君之象，地有民之象，為人上者，得不厚下以為安宅乎？雜卦曰：「剝，爛也。」剝之為義多矣。草木之落謂之剝，「八月剝棗」是也；宮室之壞謂之剝，「上九剝廬」是也；器物之爛謂之剝，「初六剝床」是也。然剝之成卦，剝以下反上，其所由來漸矣。故取喻於草木之落，不若取於宮室之壞；取於宮室之壞，不若取於器物之爛。是以剝之諸爻，皆取「剝床」為象。至於上九，然後系之以「碩果」、「剝廬」之義焉。初六：剝床以足，蔑，貞兇。象曰：「剝床以足」，以滅下也。初六，「坤」也，以陰居剛，而在一卦之下，上無其應，而承於六二，二亦「坤」也，故曰：「剝床以足，蔑。」床上實而下虛，有「剝」之象。初在下為足，體「坤」為虛。在「剝」之時，譬之床爛而其足蔑矣。「蔑」，滅也。床蔑其足，其與幾何？故曰「貞兇」。「貞」，正也，固也。以此為正，以此為固，兇其宜矣。子曰：「剝床以足，以滅下也。」「滅下」，蓋釋「以足蔑」之文，讀者遂以「蔑」連下文，失之矣。按荀本「蔑」字並作「滅」。六二：剝床以辨，蔑，貞兇。象曰：「剝床以辨」，未有與也。六二，「坤」也。以陰居柔而在下卦之中，上無其應，而承於六三，三亦「坤」也，故曰：「剝床以辨，蔑。」床簀謂之辨。「辨」，床之中，床足分辨之處也。爛其床而蔑其辨，勢已迫矣。貞而不去，兇何疑乎？故曰「貞兇」。子曰：「剝床以辨，未有與也。」「未」字當讀為「末」。「末」，無也。凡卦，六二吉多而兇少，何也？以其居正而得中也。然而有與則為正，無與則為邪。今「剝」之二，遠無所應，近無所與，陷於群陰之中，是以為「剝床」之象也。若上有九五則為「觀」；近有九三則為「賁」，何遽兇哉？或曰：剝至六三有應，故六二言「未」。於義亦通。六三：剝之，無咎。象曰：「剝之無咎」，失上下也。六三上體為「坤」，下體亦為「坤」，以陰居剛，而在下卦之上，應乎上九之「震」，故曰：「剝之無咎。」自初至五皆「剝」也。「剝」之為義兇矣，而此言「無咎」，何也？曰：重「坤」者，天下之至順也，而應乎「震」，順以動者也。順以動而謂之剝，何也？曰：上下皆「坤」，而在群陰之中，但見其順，未見其動也。雖有順動之志，而當是之時，有不可不剝者矣。夫初剝床足，二剝床辨，至三及其茵薦矣。初、二皆「兇」，而三乃「無咎」，何也？曰：初二以「坤」遇「坤」，上無其應，貞而不去，是以兇也。三以「坤」應「震」，將去之矣。雖床之剝，又何咎哉？子曰：「剝之無咎，失上下也。」上謂六四，下謂六二也。三承於四，四又「艮」也。苟無其應，斯此之矣。今以九在上，「坤」「震」相與，其於六四，宜喪其朋，無相得之理矣。四不之得，而況於二乎？三在剝之中，既為所剝矣，所以「無咎」者，失上下之情而獨應上九也。吉則未能免咎而已。六四：剝床以膚，兇。象曰：「剝床以膚」，切近災也。六四上體為「艮」，下體為「坤」，以陰居柔而在下卦之下，下無其應而承於六五，五亦「坤」也，故曰「剝床以膚」。「膚」，皮膚也。「坤」為「剝」，「艮」為「膚」。剝床而及其膚，去之晚矣，況又安寢而不去乎？故不曰「貞兇」而直言「兇」也。子曰：「剝床以膚，切近災也。」或曰：床爛及膚，猶寢地也，何遽兇乎？曰：非此之謂也。「爛」於文從火，「災」亦從火。火之熟物謂之「爛」，火之燼物謂之災。熒熒之火，先爛其足，次爛其辨，又爛其薦，以及其膚，然且熟寢而不知覺，此其所以「兇」也。賈誼所謂「厝火積薪之下而寢其上，火未然，因謂之安」，斯之謂也。「剝」之下卦自離而變，其取諸火也宜哉！故曰「為近切之災」。六五：貫魚以宮人寵，無不利。象曰：「以宮人寵」，終無尤也。六五，「坤」也，以陰居剛而在上卦之中，下無其應，而承於上九之「震」，故曰「貫魚以宮人寵」。「坤」為魚，為婦人，為眾，故有「貫魚」「宮人」之象。五陰而一陽，「貫魚」之象也；五陰順序，魚貫而進，「宮人」之象也。「剝」至於五，兇之極也，聖人有所不忍言也，謂其無應而承於「震」，故別設義以救之。五陰魚貫以承上九，上九以宮人之寵寵之，斯為善矣，非柔變剛之義也，故曰「無不利」。「以宮人寵」，寵無不被，而有尊卑之序也。夫豈特宮人為然，人君之於臣下，寵之有序，賤不妨貴，小不加大，遠不間親，新不間舊，則民志定矣，何不利之有哉？故子曰：「以宮人寵，終無尤也。」「終」之為言，其上九之謂乎？上九：碩果不食，君子得輿，小人剝廬。象曰：「君子得輿」，民所載也；「小人剝廬」，終不可用也。上九，「震」也，以陽居柔，而在一卦之上，應乎六三之「坤」，故曰「碩果」。上九之「艮」，極反而成「震」者也。「艮」為果蓏，「震」為反生。五陽盡剝，而上九獨存，故有「碩果不食」之象。「剝」，爛也；「碩」，大也。果之枝葉華實，莫不盡剝矣，而留其碩大者於其上，室於爛而不食，將以複種也。「坤」為土，「震」為動。果爛入土，陽氣動而復生矣，可「剝」而復之象也。故曰：「君子得輿，小人剝廬」。「輿」，車也，眾也。「廬」，屋也。「坤」為眾，為輿，「艮」為「廬」。陽為君子，陰為小人，故有「得輿」、「剝廬」之象。六五之剝極矣，有君子焉，民之所載也。應乎六三之「坤」，得「輿」之象也。自五以下，其象皆「坤」。既見君子，則共載之也。若以小人當之，則剝其廬矣。屋之壁、戶牖，莫不盡剝矣，而飄然茨瓦，蓋覆其上，僅有存耳。君子得之，則葺理其下而居之；小人則徹其茨瓦，剝廬而後已也。故曰：「君子得輿，民所載也；小人剝廬，終不可用也。」漢之光武，唐之肅宗，得輿者也。漢之靈、獻，唐之僖、昭，剝廬者也。彼其所用皆小人，必至於天下大壞極亂而後止也。序卦曰：「剝者，剝也。物不可以終盡，剝窮上反下，故受之以復。」「復」之成卦，剝之反也。自「剝」之復，初、上相易而成也。物窮則反，理之必至。「剝」之上九窮矣，是以反於初九而成「復」也。剝者，陰盛之象；復者，陽生之象也。方歲之寒，草木凋瘁，蟲獸蟄藏，人民廬處，山童而川冰，可謂「剝」矣。及夫一陽之生，固未盛也，而凋瘁者芽，蟄藏者奮，廬處者出，童者青而冰者泮矣，是以謂之「復」也。復：亨。出入無疾，朋來無咎。反覆其道，七日來複，利有攸往。彖曰：「復，亨」。剛反動而以順行，是以「出入無疾，朋來無咎」。「反覆其道，七日來複」，天行也。「利有攸往」，剛長也。復，其見天地之心乎？下震上坤成卦曰「復」者，初為「震」，自二以往皆為「坤」也。「震」，動也；「坤」，順也。動而順，復之義也。「震」為雷，「坤」為地。雷在地中，「復」之象也。夫陰陽之運，有如循環，方其消而為剝也，陽氣幾盡於外矣。及夫「艮」反為震，而乃出乎地中，是以謂之「復」也。復，亨，出入無疾，朋來無咎。何謂也？曰：「復」，反也。「亨」，通也。陽氣反而後通也。「出」者，震也；「入」者，艮也。初為震，而三有艮體，故有「出入」之象。「疾」，害也。方剝之時，非特不利於出也，雖入此室處，猶懼不免焉。至此而出入自如，莫或害之矣。朋，眾也。坤為眾，自外為來，故有「朋來」之象。方剝之時，君子保身之不暇，奚可以得眾乎？眾之所聚，禍之所歸也。至此則朋眾方來，而莫或咎之矣。朋之來也，非以為利也，相與反覆其道焉耳。初九以陽居剛，故諸爻反覆無非道者。故子曰：復亨，剛反也。動而以順行，是以出入無疾，朋來無咎，反覆其道也。「七日來複，利有攸往。」何謂也？曰：「七曰」之義，諸家紛然不同。大率言自剝至復為七日，皆失之矣。而六日七分，尤為繆妄。惟伊川程氏曰：「姤七變而為復。」臨川王氏曰：「陰陽之往復，以日論之可也，以月以歲論之可也。」今取之。夫陰陽之運，十二而周，故天有十二次，地有十二分，日有十二辰，歲有十二月，此其最著者也。十二辰為一日，有晝夜昏明之異也。十二月為一歲，有冬夏寒暑之變也。至於十二月為浹，十二歲為紀，旡昏明之異，無寒暑之變，其差甚微，而人弗之覺也。易之為書，微顯闡幽，故常言三日七日，以驗其近，三歲十歲，以驗其遠。至於言時月，則絕無而僅有，皆隱奧其辭，不使易而知之耳。自子至午，自午至子，其數七也。自寅至申，自申至寅，其數亦七也。在易以卦配，則自復至姤，自姤至復，其數皆七也。若自復至遁，自姤至臨，則其數八矣。夫積十二辰而以日數之者，日之一度也。積日三十而以月數之者，月之一週也。日，陽物也。月，陰物也。七，陽數也。八，陰數也。舉日稱七，故於一陽言之，正應乎七數也。舉月稱八，故於二陰言之，正應乎八數也。聖人因象以寓辭，因辭以寓意。「八月有兇，七日來複」，蓋有喜懼之辭焉，學者不可不知也。然而不言於遁，而言於臨者，此則互文見義，相為表裡，是故系之以月也。易卦以月系，惟此而已。詩言「一之日」、「二之日」，與此同意。若從卦氣之說，則剝後十卦然後為復，非但六日七分而已也。故子曰：「七日來複，天行也。」凡彖曰消長之義，夫子每以天行釋之，以為必至之理也。利有攸往，剛長也。言自復之「臨」，自臨之「泰」也。不利於「剝」，則利於「復」可知矣。故又曰：「復，其見天地之心乎？」方其未復也，天地閉塞，萬物摧殘，賢愚易其位，善惡乖其應，若無天理，惟人自為耳。故老聃氏有「天地不仁」之說，而申包胥有「人眾勝天」之語。方此時也，天地之心，何自而見哉？及其「復」也，陽氣動乎地中，一草一木，稍有芽櫱之意，其及物也幾何，而天地之心，生成之德，已自可見矣。天地者，萬物之父母；人君者，萬民之天地也。方其「剝」也，苛政以殘之，重斂以困之，用其所惡，棄其所好，民未有不以為厲已也。及其「復」也，用一賢，去一佞，發一政，施一令，其利澤曾未幾何，而人民愛物之心，已自可見矣。天下之人必曰：「吾君仁聖如此，但為小人所誤耳。」故曰：「復，其見天地之心乎？」由是言之，凡世人所謂善惡無報，天道難期者，皆由「否」、「剝」之世而論天地也。天地之大德曰生，至「復」而後心可見矣。聖人於此見天地之心，而愚於此見聖人之意也，不其然乎？象曰：雷在地中，「復」。先王以至日閉關，商旅不行，後不省方。「雷」者，「震」也。「地」者，「坤」也。「雷在地中」，「復」而將奮也。先儒皆以復為建子之月，愚於臨卦既覺其非，今以象考之，所以為復者，震也，非坎也。今夫火生於艮而王於離，歸乎乾而絕乎坎，是故絕而復生者，坎中之陽也。水生於坤而王於坎，歸乎巽而絕乎離。是故絕而復生者，離中之陰也。坎中之陽，其微若是，而以為「出入無疾，利有攸往」之象，不既疏乎？是故聖人取諸震坤，以為來複。仲春之月，雷乃發聲，則建寅之月，雷固在地中也。雖在地中，而蟄者振矣。先王觀此之象，至於來複之日，而閉關施行者，以為歲於是乎更新，萬物於是乎更始，諸侯之賓客於是乎告歸，四方之商旅於是乎啟行，巡狩省成於是乎戒事。將欲闢之，必先翕之。閉關絕行，謀始之義也。子曰：「夏殷之禮，吾能言之，杞宋不足徵也。」而況於百世之後乎？雜卦曰：「復，反也。」復之成卦，以上初反本而成。其在諸爻，以反於初九為義。反之為言，反身之謂也。夫剝復消長，本以明君子小人進退之象。然一陽之生，在乾為勿用，雖曰來複，有動順之義，方於交泰之初，則有間矣。故君子於此，出處語默猶在所擇焉，未可以勇於進也。是以六爻無利用之辭，而專明反身之義。聖人之旨，蓋可見矣。或曰：「然則彖言利有攸往，何也？」曰：「利有攸往，為主復者言之也。復而不往，則一陽而勝五陰，未見其可也。自復以往，則為臨、為泰、為壯、為夬，謂之利也，不亦宜乎？」初九：不遠復，無祇悔，元吉。象曰：「不遠」之「復」，以修身也。初九，震也。以陽居剛，而在一卦之下，配在六四，而承於六二，二、四皆「坤」也，故曰「不遠復」。「復」之初九，即「剝」之上九也。在剝為「艮」，而在復為「震」。震反則為「艮」，艮反則為「震」也。艮為冬，而震為春，「艮」東北而震居東，自冬而徂春，自北而之東，其順若循環，其易如反掌，是以謂之「不遠復」也。或曰：「然則何取於坤哉？」曰：「坤」也者，地也。艮為果蓏，震為反生，果之反而生也，非地則可乎？是故剝以一陽而入乎地，復以一陽而出乎坤，是以謂之「不遠」也。故曰：「無祗悔，元吉。」「祗」，至也。「元」，善也，大也。自「剝」而復，自「艮」而「震」，以月言之，一月也；以日言之，一日也；以行事言之，一事也；以思念言之，一念也。人誰無過，過而能改，善莫大焉。一事之過而改之，一念之失而復之，無至於悔，斯為「元吉」矣。或曰：「彖言七日來複，而吾子以為一日，何其戾哉？」曰：甚矣，子之不達也。彖言「七日來複」，自陰始，陰陽之往復，其數皆七，何以為不遠之義乎？若夫始之陰，自兌而巽，則非艮震之比也。易有言「終朝」者，有言「終日」者，有言「不終」者，有言「三日」者，至於七止矣，而以為不遠之義，不已疏乎？故順而言之也。爻言「不遠復」，自剝而復言之也。夫子曰：不遠之復，以修身也。君子知外物之不可必也，以修此身而已矣。子曰：「顏氏之子，其殆庶幾乎？有不善未嘗不知，知之未嘗復行也。」其修身之謂乎？又曰：「復，德之本也。草木歸根而後生，君子反身而後行，德之本也」。又曰：「復小而辨於物」。小之言微也。五陰而一陽，可謂微小矣。陽雖小而陰莫之傷，是謂與物辨也。又曰：「復以自新」，顏氏之謂也。六二：休復，吉。象曰：「休復」之吉，以下仁也。六二，坤也。以陰居柔，而在下卦之中。上無其應，而乘乎初九之震，故曰「休復」。休休，自得之貌。一陽為復之主，五陰朋來，反覆其道者也。以坤遇震，以六二從初九，陽上行而陰下趨，是以其心休休然，無入而不自得也，故曰「吉」。聞一善言，見一善行，沛然若決江河，莫之能御，斯之謂「吉」矣。子曰：「休復之吉，以下仁也。」初在二下，「震」為「木」，仁也。六二可謂親仁矣。不言「親仁」而言「下仁」者，謂其從之也，如水之就下矣。故曰：「仁者安仁」，初九是也；「智者利仁」，六二是也。說者乃以六二為自下於人，不亦倒置而言之乎？六三：頻復，厲，無咎。象曰：「頻復」之「厲」，義無咎也。六三上體為「坤」，下體為「艮」，以陰居剛而在下卦之上，上無其應，而連於初九之「震」，故曰「頻復」。「頻」，屢也。「坤」為順，「艮」為止。三不中不正，而乘承皆陰，將順復止，將止復順，其失道也屢矣。然而天下之動，必正乎一。當復之時，初九以一陽居下，為眾所歸。三雖不正，與初同體，雖屢失道，終必復焉，故曰「厲」。「厲」，危也。孟子有言：「欲知舜、蹠之分，無他，利與善之間耳。」屢失屢復，其去蹠也幾希。然而猶知復也，則與迷復有間矣，故曰「無咎」。聖人常善教人，故無棄人。危而能反，猶可以「無咎」也。故子曰：「頻復之厲，義無咎也。惟聖罔唸作狂，惟狂克唸作聖。困而學之，又其次也。」其六三之謂乎？六四：中行獨復。象曰：「中行獨復」，以從道也。六四上體為「坤」，下體亦為「坤」，以陰居柔而在上卦之下，應乎初九之「震」，故曰「中行獨復」。凡卦以二五為中，此獨以四為中，何也？記曰：「君子之中庸也，君子而時中。」孟子曰：「執中無權，猶執一也。」上下五陰，四居其中，群陰未復，己獨應焉，是以謂之「中行」也。或曰：六二最近於初，「復」之最先者也。四為獨復，何哉？曰：四之復也，非至是而後應也，其復也久矣。在「剝」為六三，獨應於上；在「復」為六四，獨應於初。故三失上下之情，而四先群陰之復也。「剝」之上九而無六三，何能以順而止？「復」之初九而無六四，何以能動而順？是知四為最先，而二次之也。四言「獨」而二言「休」，玩其辭而知之矣。子曰：「中行獨復，以從道也。」道也者，以別於利也。四之從初，在「剝」則然，豈為利也哉？是故爻辭不繫之吉，明其心之所存，不以吉凶而從違也。六五：敦復，無悔。象曰：「敦復無悔」，中以自考也。六五，「坤」也。以陰居剛，而在上卦之中，下無其應，而乘乎六四。四亦「坤」也，故曰「敦復」。「敦」，厚也，益也。「艮」之九三既已「艮」矣，上九謂之「敦艮」者，又從而附益之也。故「臨」之六五，正應九二，則上六為「敦臨」；「復」之六四，正應初九，則六五為「敦復」。夫六五下無所應，上無所與，苟不附於六四，則去「復」遠矣。為其居中而得其所附，是以謂之「敦復」也。復之又「復」，新之又新也，故曰「無悔」。「復」至於五，「復」之道成矣。成者，成也。自明而誠者，勉而中，思而得也。自初來複，至五而成，則幾於性矣。故「無悔」之辭，與初九同。「初無緹悔，尚或有之」，至五則「無復悔」矣。故子曰：「敦復無悔，中以自考也。」「考」，成也。君子之所以成己也。何以不成於上六，而成於六五？為其得中也。反身而誠，得其固有之中，六五之謂矣。或生而知之，或學而知之，或困而知之，及其知之，一也。或安而行之，或利而行之，或勉強而行之，及其成功，一也。上六：迷復，兇，有災眚。用行師，終有大敗，以其國君兇，至於十年不克徵。象曰：「迷復」之兇，反君道也。上六，「坤」也。以陰居柔，而在一卦之上，下無其應，而乘乎六五，亦「坤」也，故曰「迷復，迷失道也」。六之於初九，遠矣，言應則背，言親則疏，言同則異，言因則失矣，是以為「失道」也。上六之與四陰，同體乎「坤」，「坤」為順，四陰之所以「吉無咎」者，以其順而復於初也。上六雖順，而失其道矣，所謂「順非而澤，從惡若流」者也。譬之適越，北首之燕，南轅疾馳而愈遠矣，故曰「兇」，又曰「有災眚」。以迷為復，兇何免乎？災自外至，眚自己作。書曰：「天作孽，猶可違；自作孽，不可逭。」至於是也，謂之災，則有人為之咎焉；謂之眚，則有天降之罰焉。雖有聖賢，不能為之謀矣。凡上六之兇，皆剝之兇也。不言於剝而言於復者，以為苟能知復，雖剝之窮，可以無悔，以迷為復，兇乃成也。保邦而自守，猶懼不免，況用之行師乎？此所謂自作孽者也。故曰：「終有大敗，以其國君兇，至於十年不克徵。」桀、紂之亡，幽、厲之敗，皆是物也，以其國與其君皆兇也。易以近言日，以遠言年。十者，數之極也。徵，行也。至於十年不克徵，則不復可徵矣，甚之之辭也。子曰：「迷復之兇，反君道也。」書稱「有苗昏迷不恭，反道敗德」是也。君人之道，以貴下賤，以賢下不肖，則天下雖亂而可治，家國雖亡而可存，初九之所以復也。今以六居上，陰柔不中，順非而自聖，其於君道，不亦反乎？聖人之戒，可謂深切著明矣。伊尹訓大甲思庸，無俾世迷，畏上六之災也。周易經傳集解卷十二",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
